const cataloguePhoto=x=>x?.photoUrl||CATALOGUE_PHOTOS[String(x?.reference||'').trim()]?((x?.photoUrl)||('catalogue_images/'+CATALOGUE_PHOTOS[String(x?.reference||'').trim()])):'';
const refKey=x=>String(x?.reference||'').trim().toUpperCase().replace(/\s+/g,' ');
function mergeDuplicateParts(items){
 const out=[],by=new Map();
 for(const raw of (items||[])){
  const x={...raw},k=refKey(x);
  if(!k){out.push(x);continue}
  if(!by.has(k)){x.usedIn=[...new Set([...(x.usedIn||[]),x.category].filter(Boolean))];by.set(k,x);out.push(x);continue}
  const keep=by.get(k);
  keep.usedIn=[...new Set([...(keep.usedIn||[]),...(x.usedIn||[]),keep.category,x.category].filter(Boolean))];
  keep.category=keep.usedIn.join(' · ');
  if(!keep.photoUrl&&x.photoUrl)keep.photoUrl=x.photoUrl;
  keep.minQty=Math.max(+keep.minQty||0,+x.minQty||0);
  keep.qty=Math.max(+keep.qty||0,+x.qty||0);
 }
 return out
}

