async function saveDoc(key,obj,message='Enregistré'){
 saveLocal();
 try{await persistDoc(key,obj);toast('✓ '+message);return true}
 catch(e){console.error(e);toast('⚠️ Non synchronisé');alert('Enregistrement Firebase impossible. Les données restent sur cet appareil.\n\n'+(e.code||e.message));return false}
}
