function stock(){let cats=[...new Set(S.items.map(x=>x.category))],canEdit=currentProfile?.role!=='mecanicien'; $('#app').innerHTML=`<div class="toolbar"><input id="q" placeholder="Référence ou description"><select id="cat"><option value="">Toutes sections</option>${cats.map(c=>`<option>${esc(c)}</option>`).join('')}</select><select id="st"><option value="">Tous</option><option value="low">Stock bas</option><option value="spare">SPARE</option><option value="consumable">CONSUMMABLE</option></select>${canEdit?'<button class="btn primary" id="add">+ Ajouter pièce</button>':''}</div><div id="stocktable"></div>`; ['q','cat','st'].forEach(id=>$('#'+id).oninput=stockTable);if(canEdit)$('#add').onclick=()=>editItem();stockTable()}
window.viewPart=id=>{let x=S.items.find(i=>String(i.id)===String(id));if(!x)return;let canEdit=currentProfile?.role!=='mecanicien';let canMove=currentProfile?.role==='admin'||currentProfile?.role==='magasinier';$('#app').innerHTML=`<button class="btn" onclick="go('stock')">← Retour au stock</button><div class="partHero"><div class="partPhoto">${cataloguePhoto(x)?`<img src="${esc(cataloguePhoto(x))}" alt="${esc(x.reference)}" loading="lazy">`:'<div class="partPlaceholder">⚙<small>Photo de la pièce</small></div>'}</div><div class="partInfo"><span class="tag">${esc(x.category)}</span><h2>${esc(x.reference)}</h2><p class="partDesc">${esc(x.description)}</p><div class="partStats"><div><span>Stock</span><b class="${low(x)?'bad':'ok'}">${x.qty}</b></div><div><span>Minimum</span><b>${x.minQty}</b></div><div><span>Emplacement</span><b>${esc(x.location||'—')}</b></div><div><span>Type</span><b>${esc(x.type)}</b></div></div><div class="partActions">${canMove?`<button class="btn primary" onclick="quickMove('${x.id}')">↕ Entrée / sortie</button>`:''}<button class="btn" onclick="requestPart('${x.id}')">✦ Demander</button>${canEdit?`<button class="btn" onclick="editItem('${x.id}')">✎ Modifier</button>`:''}</div></div></div><div class="card partDetails"><h3>Détails</h3><div class="detailGrid"><div><span>Page catalogue</span><b>${esc(x.catalogPage||'—')}</b></div><div><span>Fournisseur</span><b>${esc(x.supplier||'—')}</b></div><div><span>Coût unitaire</span><b>${money(x.unitCost)}</b></div><div><span>Notes</span><b>${esc(x.notes||'—')}</b></div></div></div><h3>Derniers mouvements</h3>${movesTable(S.moves.filter(m=>String(m.itemId)===String(x.id)).slice().reverse().slice(0,12))}`}
window.requestPart=id=>{page='requests';nav();render();setTimeout(()=>{let s=$('#rqitem');if(s)s.value=id},0)};

function stockTable(){let q=($('#q')?.value||'').toLowerCase(),cat=$('#cat')?.value||'',st=$('#st')?.value||'';let a=S.items.filter(x=>(!q||(x.reference+' '+x.description).toLowerCase().includes(q))&&(!cat||x.category==cat)&&(!st||(st=='low'?low(x):x.type.toLowerCase()==st))); $('#stocktable').innerHTML=`<div class="stockCards">${a.map(x=>`<div class="stockCard" onclick="viewPart('${x.id}')"><div class="stockCardTop"><div class="stockThumb">${cataloguePhoto(x)?`<img src="${esc(cataloguePhoto(x))}" loading="lazy" alt="">`:'<span>⚙</span>'}</div><div><h4>${esc(x.reference)}</h4><p>${esc(x.description)}</p></div><div class="stockQty"><b class="${low(x)?'bad':'ok'}">${x.qty}</b><small>EN STOCK</small></div></div><div class="stockMeta"><span class="tag">${esc(x.type)}</span><span>${esc(x.category)}</span><span>•</span><span>${esc(x.location||'Non classé')}</span></div></div>`).join('')}</div><div class="tablewrap"><table><thead><tr><th>Référence</th><th>Description</th><th>Section</th><th>Type</th><th>Stock</th><th>Min.</th><th>Emplacement</th><th>Coût</th><th></th></tr></thead><tbody>${a.map(x=>`<tr class="${low(x)?'low':''}"><td><button class="partLink" onclick="viewPart('${x.id}')"><b>${esc(x.reference)}</b></button><br><span class="muted">Cat. p.${esc(x.catalogPage)}</span></td><td>${esc(x.description)}</td><td>${esc(x.category)}</td><td><span class="tag">${esc(x.type)}</span></td><td class="${low(x)?'bad':'ok'}">${x.qty}</td><td>${x.minQty}</td><td>${esc(x.location||'—')}</td><td>${money(x.unitCost)}</td><td class="rowactions">${currentProfile?.role!=='mecanicien'?`<button onclick="editItem('${x.id}')">✏️</button><button onclick="quickMove('${x.id}')">↕️</button>`:'Consultation'}</td></tr>`).join('')}</tbody></table></div>`}
window.editItem=id=>{if(currentProfile?.role==='mecanicien')return alert('Modification réservée au magasinier ou à l’administrateur');let x=id?S.items.find(i=>i.id==id):{id:'u-'+Date.now(),reference:'',description:'',category:'Autre',type:'SPARE',qty:0,minQty:S.settings.defaultMin||1,location:'',unitCost:0,supplier:'',notes:'',catalogPage:''}; $('#app').innerHTML=`<h2>${id?'Modifier':'Ajouter'} une pièce</h2><div class="card formgrid"><label>Référence<input id="fref" value="${esc(x.reference)}"></label><label>Description<input id="fdesc" value="${esc(x.description)}"></label><label>Section<input id="fcat" value="${esc(x.category)}"></label><label>Type<select id="ftype"><option ${x.type=='SPARE'?'selected':''}>SPARE</option><option ${x.type=='CONSUMMABLE'?'selected':''}>CONSUMMABLE</option></select></label><label>Stock actuel<input id="fqty" type="number" step="1" value="${x.qty}"></label><label>Stock minimum<input id="fmin" type="number" step="1" value="${x.minQty}"></label><label>Emplacement<input id="floc" value="${esc(x.location)}"></label><label>Coût unitaire<input id="fcost" type="number" step="0.01" value="${x.unitCost}"></label><label>Fournisseur<input id="fsup" value="${esc(x.supplier)}"></label><label>Page catalogue<input id="fpage" value="${esc(x.catalogPage)}"></label><label class="full">Lien de la photo<input id="fphoto" type="url" inputmode="url" value="${esc(x.photoUrl||'')}" placeholder="https://..."><small class="fieldHelp">Colle un lien direct vers une image Google ou un autre site.</small></label><div class="full photoPreviewBox"><span>Aperçu</span><div id="photoPreview">${cataloguePhoto(x)?`<img src="${esc(cataloguePhoto(x))}" alt="">`:'<div class="previewEmpty">🖼️ La photo apparaîtra ici</div>'}</div></div><label class="full">Notes<textarea id="fnotes">${esc(x.notes)}</textarea></label><div class="full"><button class="btn primary" id="fsave">Enregistrer</button> <button class="btn" onclick="go('stock')">Annuler</button>${id?` <button class="btn" id="fdel">Supprimer</button>`:''}</div></div>`; const previewPhoto=()=>{let u=$('#fphoto').value.trim();$('#photoPreview').innerHTML=u?`<img src="${esc(u)}" alt="Aperçu" onerror="this.parentElement.innerHTML='<div class=\'previewEmpty\'>⚠️ Ce lien ne permet pas d’afficher directement l’image</div>'">`:'<div class="previewEmpty">🖼️ La photo apparaîtra ici</div>'};$('#fphoto').addEventListener('input',previewPhoto);$('#fphoto').addEventListener('change',previewPhoto);$('#fsave').onclick=()=>{Object.assign(x,{reference:$('#fref').value.trim(),description:$('#fdesc').value.trim(),category:$('#fcat').value.trim(),type:$('#ftype').value,qty:+$('#fqty').value||0,minQty:+$('#fmin').value||0,location:$('#floc').value.trim(),unitCost:+$('#fcost').value||0,supplier:$('#fsup').value.trim(),catalogPage:$('#fpage').value.trim(),photoUrl:$('#fphoto').value.trim(),notes:$('#fnotes').value.trim()});if(!x.reference)return alert('La référence est obligatoire');let duplicate=S.items.find(i=>i!==x&&refKey(i)===refKey(x));if(duplicate)return alert('Cette référence existe déjà : '+duplicate.reference);if(!id)S.items.push(x);saveDoc('items',x,'Pièce enregistrée');go('stock')}; if(id)$('#fdel').onclick=async()=>{if(confirm('Supprimer cette pièce ?')){S.items=S.items.filter(i=>i.id!=id);saveLocal();try{await removeDoc('items',id);toast('✓ Pièce supprimée');go('stock')}catch(e){alert('Suppression Firebase impossible : '+e.message)}}}}
window.quickMove=id=>{page='move';nav();render();setTimeout(()=>{$('#mitem').value=id},0)};
function scan(){ $('#app').innerHTML=`<h2>Scanner une pièce</h2><div class="card"><p>Scanne un code-barres ou QR avec la caméra de l’iPhone. Le code peut être une référence du catalogue.</p><button class="btn primary" id="startscan">📷 Ouvrir la caméra</button><div id="scanbox" style="margin-top:12px"></div></div>`; $('#startscan').onclick=async()=>{if(!('BarcodeDetector'in window)){let code=prompt('Scanner non supporté ici. Entre la référence :');return code&&findScanned(code)};let box=$('#scanbox');box.innerHTML='<video id="cam" playsinline style="width:100%;max-width:520px;border-radius:12px"></video>';let v=$('#cam'),stream=await navigator.mediaDevices.getUserMedia({video:{facingMode:'environment'}});v.srcObject=stream;await v.play();let d=new BarcodeDetector({formats:['qr_code','code_128','ean_13','ean_8','upc_a','upc_e']});let timer=setInterval(async()=>{try{let r=await d.detect(v);if(r[0]){clearInterval(timer);stream.getTracks().forEach(t=>t.stop());findScanned(r[0].rawValue)}}catch(e){}},400)}}
function findScanned(code){let x=S.items.find(i=>i.reference.toLowerCase()==String(code).trim().toLowerCase());if(x){page='stock';nav();render();setTimeout(()=>{let q=$('#q');if(q){q.value=x.reference;stockTable()}},0)}else alert('Référence non trouvée : '+code)}
function requests(){
 S.requests=S.requests||[];
 let canApprove=currentProfile?.role==='admin'||currentProfile?.role==='magasinier';
 let opts=S.items.map(x=>`<option value="${x.id}">${esc(x.reference)} — ${esc(x.description)}</option>`).join('');
 let pending=S.requests.filter(r=>r.status==='En attente').length;
 $('#app').innerHTML=`<div class="requestsPage">
  <div class="requestHead"><div><span class="pageEyebrow">GESTION DES PIÈCES</span><h2>Demandes de pièces</h2><p>Demander une pièce du stock pour une intervention.</p></div><div class="requestCount"><b>${pending}</b><span>en attente</span></div></div>
  <div class="requestFormCard">
   <div class="requestFormTitle"><div class="requestIcon">＋</div><div><h3>Nouvelle demande</h3><p>Choisis la pièce et indique la quantité nécessaire.</p></div></div>
   <div class="requestFields">
    <label class="requestPartField"><span>Pièce</span><select id="rqitem">${opts}</select></label>
    <label><span>Quantité</span><input id="rqq" type="number" value="1" min="1"></label>
    <label><span>Machine</span><input id="rqm" value="FFG-970/2400"></label>
    <label class="requestUser"><span>Demandé par</span><input id="rqu" value="${esc(currentUser?.email||S.settings.currentUser||'')}" readonly></label>
    <label class="requestReason"><span>Motif / intervention</span><textarea id="rqn" placeholder="Ex. remplacement urgent, entretien préventif…"></textarea></label>
   </div>
   <div class="requestSubmit"><button class="btn primary" id="rqgo">Envoyer la demande <span>→</span></button></div>
  </div>
  <div class="requestListHead"><div><h3>Historique des demandes</h3><p>${S.requests.length} demande(s)</p></div></div>
  <div class="requestList">${S.requests.slice().reverse().map(r=>`<article class="requestItem">
    <div class="requestItemMain"><div class="requestPartIcon">⚙</div><div class="requestItemText"><b>${esc(r.reference)}</b><span>${esc(S.items.find(i=>String(i.id)===String(r.itemId))?.description||'Pièce de rechange')}</span><small>${esc(r.machine||'FFG-970/2400')} · ${esc(r.user||'')} · ${esc(r.date||'')}</small></div></div>
    <div class="requestQty"><span>QTÉ</span><b>${r.qty}</b></div>
    <div class="requestStatus"><span class="statusPill ${r.status==='Approuvée'?'approved':r.status==='Refusée'?'rejected':'pending'}">${r.status==='Approuvée'?'✓ ':r.status==='Refusée'?'× ':'● '}${esc(r.status)}</span>${r.note?`<small>${esc(r.note)}</small>`:''}</div>
    ${r.status==='En attente'&&canApprove?`<div class="requestActions"><button class="btn primary" onclick="approveRequest(${r.id})">✓ Approuver</button><button class="btn" onclick="rejectRequest(${r.id})">Refuser</button></div>`:''}
   </article>`).join('')||'<div class="requestEmpty">Aucune demande pour le moment.</div>'}</div>
 </div>`;
 $('#rqgo').onclick=()=>{let x=S.items.find(i=>i.id==$('#rqitem').value);if(!x)return alert('Choisis une pièce');let qty=+$('#rqq').value||0;if(qty<1)return alert('Entre une quantité valide');let r={id:Date.now(),itemId:x.id,reference:x.reference,qty,user:currentUser?.email||$('#rqu').value,userId:currentUser?.uid||'',machine:$('#rqm').value,note:$('#rqn').value,status:'En attente',date:new Date().toISOString().slice(0,10)};S.requests.push(r);saveDoc('requests',r,'Demande envoyée');render()}
}
window.approveRequest=async id=>{let r=S.requests.find(x=>x.id==id),x=S.items.find(i=>i.id==r?.itemId);if(!r||!x)return;let m={id:Date.now(),date:new Date().toISOString().slice(0,10),itemId:x.id,reference:x.reference,type:'out',qty:r.qty,doc:'DEM-'+r.id,user:r.user,machine:r.machine,note:r.note,balance:0};try{await cloud.runTransaction(cloud.db,async tr=>{let pr=cloud.doc(cloud.db,'parts',String(x.id)),ps=await tr.get(pr),qty=ps.exists()?(+ps.data().qty||0):(+x.qty||0);if(qty<r.qty)throw new Error('Stock insuffisant');let next=qty-r.qty;m.balance=next;tr.set(pr,{...x,qty:next},{merge:true});tr.set(cloud.doc(cloud.db,'requests',String(r.id)),{...r,status:'Approuvée'},{merge:true});tr.set(cloud.doc(cloud.db,'movements',String(m.id)),m)});x.qty=m.balance;r.status='Approuvée';S.moves.push(m);saveLocal();toast('✓ Demande approuvée');render()}catch(e){alert('Impossible : '+e.message)}};
window.rejectRequest=async id=>{let r=S.requests.find(x=>x.id==id);if(!r)return;r.status='Refusée';await saveDoc('requests',r,'Demande refusée');render()}
function inventory(){let cats=[...new Set(S.items.map(x=>x.category))];$('#app').innerHTML=`<div class="sectionTitle"><h2>Inventaire physique</h2><span class="tag">${S.items.length} références</span></div><div class="card"><p class="muted">Compte les pièces réellement présentes. Tu peux filtrer par section.</p><select id="invcat"><option value="">Toutes sections</option>${cats.map(x=>`<option>${esc(x)}</option>`).join('')}</select> <button class="btn primary" id="invload">Afficher les pièces</button></div><div id="invlist" class="inventoryCards"></div>`;const load=()=>{let a=S.items.filter(x=>!$('#invcat').value||x.category==$('#invcat').value);$('#invlist').innerHTML=a.map(x=>`<div class="inventoryCard"><div class="stockThumb">${cataloguePhoto(x)?`<img src="${esc(cataloguePhoto(x))}" loading="lazy" alt="">`:'<span>⚙</span>'}</div><div class="inventoryInfo"><b>${esc(x.reference)}</b><small>${esc(x.description)}</small><span>${esc(x.category)}</span></div><div class="inventoryCount"><small>Théorique</small><strong>${x.qty}</strong></div><div class="inventoryInput"><label>Compté</label><input id="inv-${x.id}" type="number" min="0" step="1" value="${x.qty}"><button class="btn primary" onclick="countItem('${x.id}')">Valider</button></div></div>`).join('')||'<div class="card">Aucune pièce dans cette section.</div>'};$('#invload').onclick=load;$('#invcat').onchange=load;load()}
window.countItem=async id=>{let x=S.items.find(i=>i.id==id),n=Math.max(0,+$('#inv-'+id).value||0);if(!x)return;let old=x.qty,m={id:Date.now(),date:new Date().toISOString().slice(0,10),itemId:x.id,reference:x.reference,type:'adjust',qty:n,doc:'INVENTAIRE',user:currentUser?.email||'',note:'Écart '+(n-old),balance:n},rec={id:'inv-'+m.id,itemId:x.id,reference:x.reference,theoretical:old,counted:n,difference:n-old,date:new Date().toISOString(),userId:currentUser?.uid||'',user:currentUser?.email||''};try{await cloud.runTransaction(cloud.db,async tr=>{tr.set(cloud.doc(cloud.db,'parts',String(x.id)),{...x,qty:n},{merge:true});tr.set(cloud.doc(cloud.db,'movements',String(m.id)),m);tr.set(cloud.doc(cloud.db,'inventories',rec.id),rec)});x.qty=n;S.moves.push(m);saveLocal();toast('✓ Inventaire enregistré');render()}catch(e){alert('Inventaire non enregistré : '+e.message)}}
function team(){
 S.employees=S.employees||[];
 let admin=currentProfile?.role==='admin';
 $('#app').innerHTML=`<div class="sectionTitle"><h2>👥 Employés</h2><span class="tag">${S.employees.length} comptes</span></div>
 ${admin?`<div class="inviteCard"><div><span class="inviteIcon">✉️</span><h3>Inviter un employé</h3><p>Envoie un lien personnel. Le rôle est attribué automatiquement à la première connexion.</p></div><div class="inviteForm"><label>Courriel<input id="invEmail" type="email" placeholder="employe@entreprise.com"></label><label>Rôle<select id="invRole"><option value="mecanicien">🔧 Mécanicien</option><option value="magasinier">📦 Magasinier</option><option value="admin">🛡️ Administrateur</option></select></label><button class="btn primary" id="sendInvite">✉️ Créer l’invitation</button></div></div>`:''}
 <div class="employeeGrid">${S.employees.map(e=>`<div class="employeeCard"><div class="employeeTop"><div class="avatar">${esc((e.name||e.email||'U')[0].toUpperCase())}</div><div><b>${esc(e.name||e.email)}</b><small>${esc(e.employeeNumber||'No employé non défini')} · ${esc(e.jobTitle||'Poste non défini')}</small><small>${esc(e.email||'')}</small></div></div><div class="employeeSummary"><span>${esc(e.department||'Service non défini')}</span><span class="employeeStatus ${e.status==='Inactif'?'inactive':''}">${esc(e.status||'Actif')}</span></div><div class="roleRow"><select id="role-${e.id}" ${admin?'':'disabled'}><option value="admin" ${e.role==='admin'?'selected':''}>🛡️ Admin</option><option value="magasinier" ${e.role==='magasinier'?'selected':''}>📦 Magasinier</option><option value="mecanicien" ${e.role==='mecanicien'?'selected':''}>🔧 Mécanicien</option></select>${admin?`<button class="btn" onclick="editEmployee('${e.id}')">Fiche</button><button class="btn" onclick="changeRole('${e.id}')">Rôle</button>`:''}</div></div>`).join('')||'<div class="card">Aucun employé.</div>'}</div>`;
 if(admin)$('#sendInvite').onclick=createInvitation;
}
window.editEmployee=id=>{
 if(currentProfile?.role!=='admin')return;
 let e=S.employees.find(x=>String(x.id)===String(id));if(!e)return;
 $('#app').innerHTML=`<div class="sectionTitle"><h2>Fiche employé</h2><button class="btn" onclick="go('team')">← Retour</button></div><div class="card formgrid employeeEdit">
 <label>Nom et prénom<input id="ename" value="${esc(e.name||'')}"></label><label>Numéro d'employé<input id="enum" value="${esc(e.employeeNumber||'')}"></label>
 <label>Poste / fonction<input id="ejob" value="${esc(e.jobTitle||'')}"></label><label>Département / service<input id="edept" value="${esc(e.department||'')}"></label>
 <label>Courriel professionnel<input id="ework" type="email" value="${esc(e.workEmail||e.email||'')}"></label><label>Téléphone<input id="ephone" type="tel" value="${esc(e.phone||'')}"></label>
 <label>Quart de travail<input id="eshift" placeholder="Jour, soir, nuit…" value="${esc(e.shift||'')}"></label><label>Date d'embauche<input id="ehire" type="date" value="${esc(e.hireDate||'')}"></label>
 <label>Statut<select id="estatus"><option ${(e.status||'Actif')==='Actif'?'selected':''}>Actif</option><option ${e.status==='Inactif'?'selected':''}>Inactif</option></select></label>
 <div class="full"><button class="btn primary" id="esave">Enregistrer la fiche</button></div></div>`;
 $('#esave').onclick=async()=>{Object.assign(e,{name:$('#ename').value.trim(),employeeNumber:$('#enum').value.trim(),jobTitle:$('#ejob').value.trim(),department:$('#edept').value.trim(),workEmail:$('#ework').value.trim(),phone:$('#ephone').value.trim(),shift:$('#eshift').value.trim(),hireDate:$('#ehire').value,status:$('#estatus').value});try{await cloud.setDoc(cloud.doc(cloud.db,'users',String(e.id)),e,{merge:true});if(currentUser?.uid===String(e.id))currentProfile={...currentProfile,...e};saveLocal();if(currentUser?.uid===String(e.id))currentProfile={...currentProfile,...e,id:currentUser.uid};toast('✓ Fiche employé enregistrée');updateAccount();go('team')}catch(err){alert('Enregistrement impossible : '+err.message)}}
}
async function createInvitation(){
 let email=$('#invEmail').value.trim().toLowerCase(),role=$('#invRole').value;
 if(!email||!email.includes('@'))return alert('Entre une adresse courriel valide.');
 let id=crypto.randomUUID?crypto.randomUUID():Date.now()+'-'+Math.random().toString(36).slice(2);
 let data={email,role,status:'pending',createdAt:new Date().toISOString(),createdBy:currentUser.uid};
 try{
  await cloud.setDoc(cloud.doc(cloud.db,'invitations',id),data);
  let link=location.origin+location.pathname+'?invite='+encodeURIComponent(id);
  let roleName=role==='admin'?'Administrateur':role==='magasinier'?'Magasinier':'Mécanicien';
  let subject='Invitation · General Emballage';
  let body='Bonjour,\n\nVous êtes invité à rejoindre l’application de gestion de stock General Emballage avec le rôle '+roleName+'.\n\nOuvrez ce lien pour créer votre compte :\n'+link+'\n\nUtilisez l’adresse '+email+' pour vous connecter.';
  if(navigator.share){try{await navigator.share({title:subject,text:body});toast('Invitation prête à envoyer');return}catch(e){if(e.name==='AbortError')return}}
  location.href='mailto:'+encodeURIComponent(email)+'?subject='+encodeURIComponent(subject)+'&body='+encodeURIComponent(body);
 }catch(e){console.error(e);alert('Invitation impossible : '+e.message)}
}
window.changeRole=async id=>{
 if(currentProfile?.role!=='admin')return alert('Réservé à l’administrateur');
 let e=S.employees.find(x=>String(x.id)===String(id)); if(!e)return;
 e.role=$('#role-'+id).value;
 try{await cloud.setDoc(cloud.doc(cloud.db,'users',String(id)),e,{merge:true});toast('Rôle modifié')}
 catch(err){alert('Modification refusée : '+err.message)}
}
function move(){let opts=S.items.map(x=>`<option value="${x.id}">${esc(x.reference)} — ${esc(x.description)}</option>`).join('');$('#app').innerHTML=`<h2>Entrée / sortie de stock</h2><div class="card formgrid"><label>Pièce<select id="mitem">${opts}</select></label><label>Type<select id="mtype"><option value="in">Entrée</option><option value="out">Sortie / consommation</option><option value="adjust">Ajustement inventaire</option></select></label><label>Quantité<input id="mqty" type="number" min="0" step="1" value="1"></label><label>Date<input id="mdate" type="date" value="${new Date().toISOString().slice(0,10)}"></label><label>Bon / demande / PO<input id="mref"></label><label>Utilisateur / technicien<input id="muser"></label><label class="full">Note<textarea id="mnote"></textarea></label><div class="full"><button class="btn primary" id="mgo">Confirmer</button></div></div><h2>Derniers mouvements</h2>${movesTable(S.moves.slice().reverse().slice(0,30))}`;$('#mgo').onclick=async()=>{let x=S.items.find(i=>i.id==$('#mitem').value),t=$('#mtype').value,q=+$('#mqty').value||0;if(!x||q<0)return alert('Quantité invalide');if(t!=='adjust'&&q<=0)return alert('Entre une quantité supérieure à 0');let old=x.qty;if(t=='out'&&q>old&&!confirm('La sortie dépasse le stock. Continuer ?'))return;let next=t==='in'?old+q:t==='out'?old-q:q,m={id:Date.now(),date:$('#mdate').value,itemId:x.id,reference:x.reference,type:t,qty:q,doc:$('#mref').value,user:$('#muser').value||currentUser?.email||'',note:$('#mnote').value,balance:next};try{await cloud.runTransaction(cloud.db,async tr=>{let pr=cloud.doc(cloud.db,'parts',String(x.id)),ps=await tr.get(pr),remote=ps.exists()?(+ps.data().qty||0):old;next=t==='in'?remote+q:t==='out'?remote-q:q;if(t==='out'&&next<0)throw new Error('Stock insuffisant');m.balance=next;tr.set(pr,{...x,qty:next},{merge:true});tr.set(cloud.doc(cloud.db,'movements',String(m.id)),m)});x.qty=next;S.moves.push(m);saveLocal();toast('✓ Mouvement enregistré');render()}catch(e){console.error(e);alert('Mouvement non enregistré : '+e.message)}}}
function movesTable(a){return `<div class="tablewrap"><table><tr><th>Date</th><th>Référence</th><th>Type</th><th>Qté</th><th>Solde</th><th>Document</th><th>Employé / Machine</th></tr>${a.map(m=>`<tr><td>${esc(m.date)}</td><td>${esc(m.reference)}</td><td>${m.type}</td><td>${m.qty}</td><td>${m.balance}</td><td>${esc(m.doc||'')}</td><td>${esc(m.user||'')} ${m.machine?'· '+esc(m.machine):''}</td></tr>`).join('')}</table></div>`}
function orders(){ $('#app').innerHTML=`<div class="sectionTitle"><h2>Commandes fournisseurs</h2><button class="btn primary" id="newpo">+ Nouvelle commande</button></div>${S.orders.length?`<div class="tablewrap"><table><tr><th>PO</th><th>Date</th><th>Fournisseur</th><th>Référence</th><th>Qté</th><th>Prix</th><th>Statut</th><th></th></tr>${S.orders.slice().reverse().map(o=>`<tr><td>${esc(o.po)}</td><td>${esc(o.date)}</td><td>${esc(o.supplier)}</td><td>${esc(o.reference)}</td><td>${o.qty}</td><td>${money(o.price)}</td><td>${esc(o.status)}</td><td><button onclick="receivePO(${o.id})">Réception</button></td></tr>`).join('')}</table></div>`:'<div class="card">Aucune commande.</div>'}`;$('#newpo').onclick=newPO}
function newPO(){let opts=S.items.map(x=>`<option value="${x.id}">${esc(x.reference)} — ${esc(x.description)}</option>`).join('');$('#app').innerHTML=`<h2>Nouvelle commande</h2><div class="card formgrid"><label>No PO<input id="po" value="PO-${new Date().getFullYear()}-${String(S.orders.length+1).padStart(3,'0')}"></label><label>Date<input id="pod" type="date" value="${new Date().toISOString().slice(0,10)}"></label><label>Fournisseur<input id="pos"></label><label>Pièce<select id="poi">${opts}</select></label><label>Quantité<input id="poq" type="number" value="1"></label><label>Prix unitaire<input id="pop" type="number" step="0.01"></label><label>Statut<select id="post"><option>À commander</option><option>Commandée</option><option>Partielle</option><option>Reçue</option></select></label><label class="full">Note<textarea id="pon"></textarea></label><div><button class="btn primary" id="posave">Enregistrer</button></div></div>`;$('#posave').onclick=()=>{let x=S.items.find(i=>i.id==$('#poi').value);let o={id:Date.now(),po:$('#po').value,date:$('#pod').value,supplier:$('#pos').value,itemId:x.id,reference:x.reference,qty:+$('#poq').value||0,price:+$('#pop').value||0,status:$('#post').value,note:$('#pon').value};S.orders.push(o);saveDoc('orders',o,'Commande enregistrée');go('orders')}}
window.receivePO=async id=>{let o=S.orders.find(x=>x.id==id),x=S.items.find(i=>i.id==o?.itemId);if(!x)return;let q=+(prompt('Quantité reçue',o.qty)||0);if(q<=0)return;let m={id:Date.now(),date:new Date().toISOString().slice(0,10),itemId:x.id,reference:x.reference,type:'in',qty:q,doc:o.po,user:currentUser?.email||'',note:'Réception commande',balance:0};try{await cloud.runTransaction(cloud.db,async tr=>{let pr=cloud.doc(cloud.db,'parts',String(x.id)),ps=await tr.get(pr),qty=ps.exists()?(+ps.data().qty||0):(+x.qty||0);m.balance=qty+q;o.status=q>=o.qty?'Reçue':'Partielle';tr.set(pr,{...x,qty:m.balance},{merge:true});tr.set(cloud.doc(cloud.db,'orders',String(o.id)),o,{merge:true});tr.set(cloud.doc(cloud.db,'movements',String(m.id)),m)});x.qty=m.balance;S.moves.push(m);saveLocal();toast('✓ Réception enregistrée');render()}catch(e){alert('Réception non enregistrée : '+e.message)}}
function suppliers(){ $('#app').innerHTML=`<div class="sectionTitle"><h2>Fournisseurs</h2><button class="btn primary" id="adds">+ Ajouter</button></div>${S.suppliers.map(s=>`<div class="card" style="margin-bottom:8px"><b>${esc(s.name)}</b><div class="muted">${esc(s.contact||'')} ${esc(s.email||'')} ${esc(s.phone||'')}</div></div>`).join('')||'<div class="card">Aucun fournisseur enregistré.</div>'}`;$('#adds').onclick=()=>{let name=prompt('Nom du fournisseur');if(!name)return;let s={id:Date.now(),name,contact:prompt('Contact')||'',email:prompt('Courriel')||'',phone:prompt('Téléphone')||''};S.suppliers.push(s);saveDoc('suppliers',s,'Fournisseur enregistré');render()}}
function alerts(){let a=S.items.filter(low).sort((x,y)=>(x.qty-x.minQty)-(y.qty-y.minQty));$('#app').innerHTML=`<h2>Alertes de réapprovisionnement</h2>${a.map(x=>`<div class="alert"><b>${esc(x.reference)}</b> — ${esc(x.description)}<br>Stock: <b>${x.qty}</b> / minimum ${x.minQty} · à commander: <b>${Math.max(0,x.minQty*2-x.qty)}</b> · ${esc(x.location||'emplacement non défini')}</div>`).join('')||'<div class="card">Tout est au-dessus du minimum.</div>'}`}
function reports(){let val=S.items.reduce((a,x)=>a+x.qty*x.unitCost,0),cons={};S.moves.filter(m=>m.type=='out').forEach(m=>cons[m.reference]=(cons[m.reference]||0)+(+m.qty||0));let top=Object.entries(cons).sort((a,b)=>b[1]-a[1]).slice(0,10);$('#app').innerHTML=`<h2>Rapports & sauvegarde</h2><div class="grid"><div class="card metric"><span>Valeur stock</span><b>${money(val)}</b></div><div class="card metric"><span>Mouvements</span><b>${S.moves.length}</b></div><div class="card metric"><span>Commandes ouvertes</span><b>${S.orders.filter(o=>o.status!='Reçue').length}</b></div></div><div class="card" style="margin-top:12px"><h3>Export / import</h3><p class="muted">Sauvegarde complète sur ton téléphone/ordinateur. Le fichier JSON restaure tout.</p><button class="btn primary" onclick="exportJSON()">Exporter sauvegarde JSON</button> <button class="btn" onclick="exportCSV()">Exporter stock CSV</button> <label class="btn">Importer JSON<input id="imp" type="file" accept="application/json" hidden></label></div><h3>Pièces les plus consommées</h3><div class="card">${top.map(([r,q])=>`<div><b>${esc(r)}</b> — ${q} unité(s)</div>`).join('')||'Pas encore de consommation.'}</div><h3>Historique : qui a pris quoi</h3>${movesTable(S.moves.slice().reverse())}`;$('#imp').onchange=e=>{let f=e.target.files[0],r=new FileReader();r.onload=()=>{try{S=JSON.parse(r.result);save();render()}catch(e){alert('Fichier invalide')}};r.readAsText(f)}}
function dl(name,text,type){let a=document.createElement('a');a.href=URL.createObjectURL(new Blob([text],{type}));a.download=name;a.click();URL.revokeObjectURL(a.href)}
window.exportJSON=()=>dl('stock-macarbox-backup.json',JSON.stringify(S,null,2),'application/json');window.exportCSV=()=>{let rows=[['Reference','Description','Section','Type','Stock','Minimum','Emplacement','Cout']].concat(S.items.map(x=>[x.reference,x.description,x.category,x.type,x.qty,x.minQty,x.location,x.unitCost]));dl('stock-macarbox.csv',rows.map(r=>r.map(v=>'"'+String(v??'').replaceAll('"','""')+'"').join(',')).join('\n'),'text/csv')}
function settings(){ $('#app').innerHTML=`<h2>Réglages</h2><div class="card formgrid"><label>Entreprise<input id="setco" value="${esc(S.settings.company||'')}"></label><label>Devise<select id="setcur"><option ${S.settings.currency=='CAD'?'selected':''}>CAD</option><option ${S.settings.currency=='EUR'?'selected':''}>EUR</option><option ${S.settings.currency=='USD'?'selected':''}>USD</option></select></label><label>Minimum par défaut<input id="setmin" type="number" value="${S.settings.defaultMin||1}"></label><div class="full"><button class="btn primary" id="setsave">Enregistrer</button> <button class="btn" id="resetcat">Réinitialiser catalogue</button></div></div><div class="card" style="margin-top:12px"><b>Catalogue chargé:</b> FFG-970/2400 #196 · Issue 04/2020<br><span class="muted">${S.items.length} lignes de pièces, sections mécaniques A1–A6/A3.1 et électriques B1–B7.</span></div>`;$('#setsave').onclick=()=>{S.settings={...S.settings,company:$('#setco').value,currency:$('#setcur').value,defaultMin:+$('#setmin').value||1};saveSettings();render()};$('#resetcat').onclick=()=>{if(confirm('Réinitialiser les pièces du catalogue ? Les mouvements et commandes restent.')){let old=new Map(S.items.map(x=>[x.category+'|'+x.reference,x]));S.items=mergeDuplicateParts(structuredClone(window.CATALOG)).map(x=>Object.assign(x,old.get(x.category+'|'+x.reference)||{}));save();render()}}}
let deferred;window.addEventListener('beforeinstallprompt',e=>{e.preventDefault();deferred=e;$('#installBtn').hidden=false});$('#installBtn').onclick=async()=>{if(deferred){deferred.prompt();await deferred.userChoice;deferred=null;$('#installBtn').hidden=true}};if('serviceWorker'in navigator){
 let refreshing=false;
 const showUpdate=reg=>{
  if(!reg?.waiting)return;
  let old=document.querySelector('#updateBanner');if(old)return;
  let b=document.createElement('div');b.id='updateBanner';b.className='updateBanner';
  b.innerHTML='<div><b>Nouvelle version disponible</b><span>Une mise à jour de General Emballage est prête.</span></div><button id="applyUpdate">Mettre à jour</button>';
  document.body.appendChild(b);
  b.querySelector('#applyUpdate').onclick=()=>{b.querySelector('button').disabled=true;b.querySelector('button').textContent='Mise à jour…';reg.waiting.postMessage({type:'SKIP_WAITING'})};
 };
 navigator.serviceWorker.addEventListener('controllerchange',()=>{if(refreshing)return;refreshing=true;location.reload()});
 navigator.serviceWorker.register('sw.js').then(reg=>{
  showUpdate(reg);
  reg.addEventListener('updatefound',()=>{let w=reg.installing;if(!w)return;w.addEventListener('statechange',()=>{if(w.state==='installed'&&navigator.serviceWorker.controller)showUpdate(reg)})});
  setInterval(()=>reg.update().catch(()=>{}),15*60*1000);
  document.addEventListener('visibilitychange',()=>{if(document.visibilityState==='visible')reg.update().catch(()=>{})});
 }).catch(e=>console.warn('Service worker',e));
}
initCloud();

function openMenu(){document.querySelector('#nav')?.classList.add('open');document.querySelector('#menuBackdrop')?.classList.add('open');document.body.style.overflow='hidden'}
function closeMenu(){document.querySelector('#nav')?.classList.remove('open');document.querySelector('#menuBackdrop')?.classList.remove('open');document.body.style.overflow=''}
document.querySelector('#menuBtn')?.addEventListener('click',()=>document.querySelector('#nav')?.classList.contains('open')?closeMenu():openMenu());document.querySelector('#menuBackdrop')?.addEventListener('click',closeMenu);
